insert into public.settings(id,data) values (1,'{"phone": "237652089193", "phoneDisplay": "6 52 08 91 93", "city": "Douala", "siteUrl": "", "heroTitle1": "La touche en plus,", "heroTitle2": "c’est R-Case.", "heroLead": "L’accessoire qui fait parler de toi.", "heroText": "Coques, cordons et étuis AirPods choisis un par un, en petites quantités. Tu commandes en un message WhatsApp, on te livre vite à Douala.", "kicker": "Nouvelle collection", "slideTitle": "Tout le monde va te demander *où tu l’as eue.*", "slideSub": "Coques, cordons et étuis AirPods choisis un par un. Chaque modèle existe en très peu d’exemplaires.", "shopTitle": "La boutique", "shopSub": "Des coques qui font parler, des cordons qu’on remarque, des étuis qui changent tout. Chaque pièce a été choisie à la main, et la plupart n’existent qu’en un ou deux exemplaires : celle qui te plaît aujourd’hui ne sera peut-être plus là demain.", "footerTitle": "Ton téléphone mérite mieux qu’une *coque ordinaire.*", "footerText": "Des coques, des cordons et des étuis AirPods sélectionnés avec soin, pour que ton téléphone te ressemble. Tu choisis, tu envoies ton panier sur WhatsApp, on s’occupe du reste.", "footerTag": "Accessoires choisis un par un, pour celles et ceux qui aiment qu’on remarque leur téléphone."}'::jsonb) on conflict (id) do update set data = excluded.data;
